+fn msr_writable_bits(field_mask: u32) -> u32 {
+    let mut writable = 0;
+    if field_mask & MSR_FIELD_FLAGS != 0 {
+        writable |= 0xFF00_0000;
+    }
+    if field_mask & MSR_FIELD_CONTROL != 0 {
+        writable |= 0x0000_00FF;
+    }
